function reviewOwnVisibleTools(){
 if(!S.user?.reviewService)return '';
 queueMicrotask(reviewBindModerationEntry);
 queueMicrotask(reviewRefreshReceivedCount);
 return btn('服务实践与历史','review-owned-practices','ghost')+btn('服务教程与历史','review-owned-visible','ghost')+btn('我的讨论档案','review-owned-discussions','ghost')+btn('收到的回复','review-received-replies','ghost')+btn('我的举报','review-my-discussion-reports','ghost')+'<span id="discussion-moderation-entry" hidden></span>';
}
function reviewOwnedTargets(t){if(t.targetSnapshot)return `<p class="pre small">当时完整目标：${esc(t.targetSnapshot.goal)}</p>`;if(!t.targetSnapshots?.length)return '<p class="small muted">这份旧资料没有可核对的完整目标版本；未用当前定义补造历史。</p>';return t.targetSnapshots.map(p=>`<p class="pre small">${esc(p.target.title)} · 目标 v${p.target.version}<br>${esc(p.target.goal)}<br>目标起步：${esc(p.target.five)}</p>`).join('')}
function reviewOwnedLocalMethod(t){const n=S.nodes.find(n=>n.id===t.sourceOrigin?.nodeId),m=n?.methods?.find(m=>m.id===t.sourceOrigin?.methodId&&m.author===S.user?.name);if(!n||!m||m.versions.at(-1)?.number!==t.sourceOrigin.sourceVersion||!t.targetSnapshots?.some(p=>p.ref.originId===n.id&&p.target.version===n.version&&['title','goal','five','domain','branch','ownership','visibility'].every(k=>p.target[k]===n[k])))return null;return {n,m}}
async function reviewOpenOwnedVisible(){
 const context=reviewContext();modal('<h2>本人服务教程与历史</h2><p class="small muted">本人在目录、私人目标和个人公开目标下保存的教程集中在这里。历史按当时已保存的目标关联展示，缺失版本不补造。</p><p id="owned-visible-status" class="small muted" role="status">正在读取…</p><div id="owned-visible-results"></div>','','本人教程历史');const host=document.getElementById('owned-visible-results'),status=document.getElementById('owned-visible-status');
 try{const r=await reviewKnowledgeRequest('/api/review-owned-tutorials',{context});if(!host.isConnected||!reviewContextCurrent(context))return;if(r.ownerId!==context.ownerId||!Array.isArray(r.tutorials))throw Error('本人教程回执不一致。');status.textContent=`本人保存 ${r.tutorials.length} 份服务教程。`;host.innerHTML=r.tutorials.map((t,i)=>`<article class="list-row"><h3>${esc(t.title)}</h3><p class="small muted">${t.archived?'已归档':t.visibility==='public'?'原保存范围：公开':'私人保存'} · ${{'personal-public':'个人公开目标','personal-private':'私人目标',catalog:'公共目录',unmapped:'旧资料，目标版本未绑定'}[t.kind]||'目标版本关联'}</p><details class="saved-notes"><summary>查看已保存内容与目标</summary><p class="pre">${esc(t.method)}</p><p class="pre small">教程五分钟：${esc(t.startAction)}</p>${reviewOwnedTargets(t)}${t.resources.map(a=>`<p class="small"><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.label)}</a> · ${a.optional?'可选':'所需'}${a.affiliate?' · 分成外链':''}</p>`).join('')}</details><details class="saved-notes"><summary>教程历史（${t.versions.length} 个版本）</summary>${t.versions.map(v=>`<section class="list-row"><p class="small muted">${esc(v.createdAt)} · ${esc(v.version.slice(0,8))} · ${v.visibility==='public'?'原公开版本':'私人版本'}</p><p class="pre small">${esc(v.method)}</p><p class="pre small">五分钟：${esc(v.startAction)}</p>${reviewOwnedTargets(v)}${v.resources.map(a=>`<p class="small"><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">${esc(a.label)}</a> · ${a.optional?'可选':'所需'}${a.affiliate?' · 分成外链':''}</p>`).join('')}</section>`).join('')}</details>${t.targetSnapshot&&!t.canPublishCurrent?'<p class="small muted">目标目前不可公开选用或已修订；原快照保留。</p>':''}${!t.archived&&t.targetSnapshot?`<button class="ghost" data-owned-visible-edit="${i}">修订私人版本</button>`:!t.archived&&reviewOwnedLocalMethod(t)?`<button class="ghost" data-owned-local-edit="${i}">从对应本机方法修订</button>`:''}</article>`).join('')||'<p class="small muted">本人尚未在服务保存教程。</p>';
  host.querySelectorAll('[data-owned-visible-edit]').forEach(b=>b.addEventListener('click',()=>{if(b.isConnected&&reviewContextCurrent(context)){const t=r.tutorials[Number(b.dataset.ownedVisibleEdit)];reviewContributeVisible(t.targetSnapshot,context,t,true)}}));host.querySelectorAll('[data-owned-local-edit]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||!reviewContextCurrent(context))return;const current=reviewOwnedLocalMethod(r.tutorials[Number(b.dataset.ownedLocalEdit)]);if(!current){status.textContent='本机方法或目标版本已变化，请重新核对。';return}methodForm(current.n,current.m)}));
 }catch(e){if(host.isConnected&&reviewContextCurrent(context))status.textContent=e.message}
}
